macro_rules! stdio_handle_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function stdio_handle in module {}", module_path!());
    };
}

mkfn!{
    stdio_handle_introspect!();
    fn stdio_handle (raw : RawHandle) -> RawHandle { if raw == sys :: c :: INVALID_HANDLE_VALUE { ptr :: null_mut () } else { raw } }
}
